const raw = ($json.choices[0].message.content || '').toString();
let text = raw;
text = text.replace(/<think>[\s\S]*?<\/think>/gi, '');
text = text.replace(/\\n/g, ' ');
text = text.replace(/```[\s\S]*?```/g, '');
text = text.replace(/`([^`]+)`/g, '$1');
text = text.replace(/^#{1,6}\s+/gm, '');
text = text.replace(/\*{1,3}([^*\n]+)\*{1,3}/g, '$1');
text = text.replace(/_{1,3}([^_\n]+)_{1,3}/g, '$1');
text = text.replace(/^[\*\-\+]\s+/gm, '');
text = text.replace(/^\d+\.\s+/gm, '');
text = text.replace(/^[\-\*_]{3,}\s*$/gm, '');
text = text.replace(/\n{3,}/g, '\n\n');
text = text.trim();
return { json: { cleanResponse: text, usage: $json.usage } };

function parseClass(raw) {
  const text = (raw || '').toString().trim();
  let classification = 'UNCERTAIN';
  let domain = 'NONE';
  try {
    const s = text.indexOf('{');
    const e = text.lastIndexOf('}');
    if (s !== -1 && e > s) {
      const p = JSON.parse(text.substring(s, e + 1));
      if (p.classification) classification = p.classification;
      if (p.domain) domain = p.domain;
    }
  } catch (err) {
    const cm = text.match(/classification[^A-Z]*([A-Z_]+)/);
    const dm = text.match(/domain[^A-Z]*([A-Z_]+)/);
    if (cm) classification = cm[1];
    if (dm) domain = dm[1];
  }
  const vc = ['SENSITIVE', 'STANDARD', 'UNCERTAIN'];
  const vd = ['PII', 'FINANCIALS', 'STRATEGIC', 'CREDENTIALS', 'LEGAL', 'MEDICAL', 'HR', 'NAMED_INDIVIDUAL', 'NONE'];
  if (!vc.includes(classification)) classification = 'UNCERTAIN';
  if (!vd.includes(domain)) domain = 'NONE';
  return { classification, domain };
}
const qClass = parseClass($('Classify Query').item.json.choices[0].message.content);
const rClass = parseClass($json.choices[0].message.content);
const genU = $('Strip Markdown').item.json.usage || {};
const qU = $('Classify Query').item.json.usage || {};
const rU = $json.usage || {};
return {
  json: {
    'Timestamp': new Date().toISOString(),
    'User ID': $('Set Start Time').item.json['User ID'],
    'query': $('Set Start Time').item.json['Query'],
    'response': $('Strip Markdown').item.json.cleanResponse,
    'response class': rClass.classification,
    'response domain': rClass.domain,
    'query class': qClass.classification,
    'query domain': qClass.domain,
    'input tokens': (genU.prompt_tokens || 0) + (qU.prompt_tokens || 0) + (rU.prompt_tokens || 0),
    'output tokens': (genU.completion_tokens || 0) + (qU.completion_tokens || 0) + (rU.completion_tokens || 0),
    'latency ms': Date.now() - $('Set Start Time').item.json.startTime,
    'est cost': 0
  }
};
